style.css:
@-moz-document domain("mail.google.com"), domain("drive.google.com"), domain("docs.google.com"), domain("sheets.google.com"), domain("slides.google.com"), domain("calendar.google.com") {
/* === Core OLED Base === */
  body, html {
    background-color: #000 !important;
    color: #e0e0e0 !important;
  }
  
  /* All containers and panels */
  div, section, aside, nav, header, footer {
    background-color: #000 !important;
    border-color: #1a1a1a !important;
  }
  
  /* === Cards and elevated surfaces === */
  [role="main"], [role="dialog"], [role="complementary"],
  .card, .panel, .sidebar, .modal {
    background-color: #0a0a0a !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.8) !important;
  }
  
  /* === Text and readability === */
  p, span, label, a, li, td, th, h1, h2, h3, h4, h5, h6 {
    color: #e0e0e0 !important;
  }
  
  /* Links - muted blue for OLED */
  a {
    color: #4a9eff !important;
  }
  
  a:hover {
    color: #6bb3ff !important;
  }
  
  /* === Input fields === */
  input, textarea, select, [contenteditable="true"] {
    background-color: #0d0d0d !important;
    color: #e0e0e0 !important;
    border: 1px solid #2a2a2a !important;
  }
  
  input:focus, textarea:focus {
    border-color: #3a3a3a !important;
    outline: none !important;
  }
  
  /* === Buttons === */
  button, [role="button"] {
    background-color: #1a1a1a !important;
    color: #e0e0e0 !important;
    border: 1px solid #2a2a2a !important;
  }
  
  button:hover, [role="button"]:hover {
    background-color: #252525 !important;
  }
  
  /* Primary action buttons */
  button[data-primary="true"],
  .primary-button,
  [aria-label*="Send"] {
    background-color: #1a4d2e !important;
    color: #90ee90 !important;
  }
  
  /* === Gmail specific === */
  /* Email list */
  .ae4, .zA, tr {
    background-color: #000 !important;
  }
  
  tr:hover, .zA:hover {
    background-color: #0d0d0d !important;
  }
  
  /* Selected email */
  .x7 {
    background-color: #1a1a1a !important;
  }
  
  /* === Google Docs/Sheets canvas === */
  .kix-page, .docs-sheet-container {
    background-color: #0a0a0a !important;
  }
  
  /* Document page (keep slightly lighter for contrast) */
  .kix-page-content-wrapper {
    background-color: #1a1a1a !important;
  }
  
  /* === Scrollbars === */
  ::-webkit-scrollbar {
    width: 12px;
    background-color: #000 !important;
  }
  
  ::-webkit-scrollbar-thumb {
    background-color: #2a2a2a !important;
    border-radius: 6px;
  }
  
  ::-webkit-scrollbar-thumb:hover {
    background-color: #3a3a3a !important;
  }
  
  /* === Reduce bright whites === */
  svg, img {
    filter: brightness(0.85) !important;
  }
  
  /* Icons - reduce brightness */
  [role="img"], .icon {
    filter: brightness(0.8) !important;
  }
}
